import{_ as t,a as r,b as e,c as i,d as s,e as o,f as l}from"./chunks/packing-7.BCH4HY69.js";import{_ as c}from"./chunks/packing-8.BybpqEe_.js";import{_ as d,o as n,c as p,a5 as h}from"./chunks/framework.DGp912Ge.js";const P=JSON.parse('{"title":"포장","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/operation/packing.md","filePath":"ko/manual/operation/packing.md","lastUpdated":1785806767000}'),u={name:"ko/manual/operation/packing.md"};function b(_,a,m,f,g,k){return n(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="포장" tabindex="-1">포장 <a class="header-anchor" href="#포장" aria-label="Permalink to &quot;포장&quot;">​</a></h1><p>RBQ10은 주로 펠리칸 케이스를 사용하여 보관 및 운반합니다. 사용되는 펠리칸 케이스 모델은 1730 Protector Case입니다. 아래 이미지를 참고하여 RBQ10과 기타 구성품을 수납하세요.</p><h2 id="로봇-포장-개봉-방법" tabindex="-1">로봇 포장/개봉 방법 <a class="header-anchor" href="#로봇-포장-개봉-방법" aria-label="Permalink to &quot;로봇 포장/개봉 방법&quot;">​</a></h2><p>펠리칸 케이스는 두 개의 층으로 나뉩니다. 하단 층에는 충전기, 예비 고무 발, 라이다를 수납하고, 그 위에 RBQ10을 올려놓습니다.</p><figure><img src="'+t+'" alt="펠리칸 케이스 하단 층 구성 예시"></figure><p>하단 층에 구성품을 배치한 후, 그림과 같이 로봇을 운반하여 케이스 안에 넣습니다.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>로봇은 반드시 두 사람이 함께 운반해야 합니다.</p></div></div><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>로봇을 운반하기 전에, 부착된 추가 장비를 모두 제거하고 전원을 끄세요.</p></div></div><figure><img src="'+r+'" alt="로봇을 케이스로 운반하는 모습"></figure><p>RBQ10을 바닥에 내려놓은 후, 그림과 같이 다리를 펼칩니다.</p><p>빨간색으로 표시된 다리 부분을 두 사람이 각각 하나씩 잡고 운반합니다.</p><figure><img src="'+e+'" alt="다리를 펼친 상태에서 운반"></figure><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>무릎 관절 회전 부위에 이물질이 들어가지 않도록 주의하고, 손가락이 끼이지 않도록 조심하세요!</p></div></div><figure><img src="'+i+'" alt="무릎 관절 주의 및 자세"></figure><p>로봇을 펠리칸 1730 케이스 안에 케이스 형상에 맞추어 넣습니다.</p><p>로봇 본체를 케이스에 넣은 후, 다음 순서로 다리를 접습니다:</p><h3 id="_1단계-앞다리의-무릎-관절을-끝까지-접습니다" tabindex="-1">1단계: 앞다리의 무릎 관절을 끝까지 접습니다 <a class="header-anchor" href="#_1단계-앞다리의-무릎-관절을-끝까지-접습니다" aria-label="Permalink to &quot;1단계: 앞다리의 무릎 관절을 끝까지 접습니다&quot;">​</a></h3><figure><img src="'+s+'" alt="앞다리 무릎 관절 접기 1단계"></figure><h3 id="_2단계-앞다리의-힙-피치-관절을-회전시켜-다리를-케이스-홈에-넣습니다" tabindex="-1">2단계: 앞다리의 힙 피치 관절을 회전시켜 다리를 케이스 홈에 넣습니다 <a class="header-anchor" href="#_2단계-앞다리의-힙-피치-관절을-회전시켜-다리를-케이스-홈에-넣습니다" aria-label="Permalink to &quot;2단계: 앞다리의 힙 피치 관절을 회전시켜 다리를 케이스 홈에 넣습니다&quot;">​</a></h3><figure><img src="'+o+'" alt="앞다리 힙 피치 회전 2단계"></figure><figure><img src="'+l+'" alt="앞다리 케이스 홈에 배치 2단계(추가)"></figure><h3 id="_3단계-뒷다리의-힙-피치-관절을-회전시켜-다리가-앞다리-허벅지-위로-가도록-합니다" tabindex="-1">3단계: 뒷다리의 힙 피치 관절을 회전시켜 다리가 앞다리 허벅지 위로 가도록 합니다 <a class="header-anchor" href="#_3단계-뒷다리의-힙-피치-관절을-회전시켜-다리가-앞다리-허벅지-위로-가도록-합니다" aria-label="Permalink to &quot;3단계: 뒷다리의 힙 피치 관절을 회전시켜 다리가 앞다리 허벅지 위로 가도록 합니다&quot;">​</a></h3><h3 id="_4단계-뒷다리의-정강이를-완전히-펼칩니다" tabindex="-1">4단계: 뒷다리의 정강이를 완전히 펼칩니다 <a class="header-anchor" href="#_4단계-뒷다리의-정강이를-완전히-펼칩니다" aria-label="Permalink to &quot;4단계: 뒷다리의 정강이를 완전히 펼칩니다&quot;">​</a></h3><figure><img src="'+c+'" alt="뒷다리 정강이 펴기 4단계"></figure><p>리모컨은 로봇 옆 수납 공간에 넣습니다. 남은 빈 공간은 자유롭게 활용할 수 있습니다.</p><p>마지막으로 덮개를 닫으면 포장이 완료됩니다.</p><p>개봉은 위 단계의 역순으로 진행합니다.</p><h2 id="포장-치수" tabindex="-1">포장 치수 <a class="header-anchor" href="#포장-치수" aria-label="Permalink to &quot;포장 치수&quot;">​</a></h2><p><b>포장 치수</b></p><table><tr><th>케이스 종류</th><th>외형 치수</th><th>무게 (빈 케이스)</th></tr><tr><td>Pelican 1730 Protector Case</td><td> 37.50 x 27.13 x 14.37&quot; (inch)<br> 86.3 x 60.9 x 31.7 (cm) </td><td> 44 lbs / 20 kg </td></tr></table><h2 id="포장-구성품" tabindex="-1">포장 구성품 <a class="header-anchor" href="#포장-구성품" aria-label="Permalink to &quot;포장 구성품&quot;">​</a></h2><p><b>포장 구성품</b></p><p>옵션 항목에 따라 구성품이 달라질 수 있습니다.</p><table><tr><th>구분</th><th>구성품</th></tr><tr><td>기본 구성</td><td> RBQ10 × 1대<br> 배터리 충전기 × 1개<br> 예비 고무 발 × 4개<br> 예비 바디 범퍼<br> 리모컨 × 1개<br> 기본 공구(렌치) × 1세트 </td></tr><tr><td>내비게이션 팩</td><td> 기본 구성품 포함<br> 라이다 모듈 × 1개 </td></tr></table>',34)])])}const B=d(u,[["render",b]]);export{P as __pageData,B as default};
